new="function drawKungfu(times=1){const n=Number(times)===5?5:1,cost=n*300;if(state.player.gems<cost)return alert(`元宝不足，需要${cost}元宝。`);state.player.gems-=cost;const reds=[];let fragments=0;for(let i=0;i<n;i++){state.kungfu.drawCount=Number(state.kungfu.drawCount||0)+1;if(Math.random()<.02){const ids=Object.keys(RED_KUNGFU),id=ids[Math.floor(Math.random()*ids.length)];addKungfuCopy(id,1);reds.push(RED_KUNGFU[id].name);}else{state.kungfu.fragments=Number(state.kungfu.fragments||0)+1;fragments++;}}commit();const redText=reds.length?`红色功法：${reds.map(x=>`【${x}】`).join('、')}`:'未获得红色功法';alert(`藏经阁抽取${n}次：${redText}${fragments?`；功法残页 +${fragments}`:''}。`);}"
assert old in s
s=s.replace(old,new)
marker="function recharge(yuan){"
