inner_funcs=r'''function assignInnerRoom(){if(state.player.chapter<INNER_POWER_OPEN_CHAPTER)return alert(`内力系统第${INNER_POWER_OPEN_CHAPTER}幕开放。`);ensureGrowthHero();if(innerPowerRoomIndex(selectedGrowthHero)>=0)return;const index=(state.innerPower?.rooms||[]).findIndex(x=>!x);if(index<0)return alert('七个练功房都有人。');state.innerPower.rooms[index]=selectedGrowthHero;state.innerPower.lastTick=Date.now();commit();}
function leaveInnerRoom(){ensureGrowthHero();recoverInnerPower(state);const index=innerPowerRoomIndex(selectedGrowthHero);if(index<0)return;state.innerPower.rooms[index]=null;state.innerPower.lastTick=Date.now();commit();}
function useInnerMedicine(key){ensureGrowthHero();const m=INNER_POWER_MEDICINES[key],h=state.heroes[selectedGrowthHero],ip=h?.innerPower;if(!m||!ip)return;const count=Number(state.innerPower?.items?.[key]||0);if(count<=0)return alert(`${m.name}不足。`);if(ip.year<m.minYear||ip.year>m.maxYear)return alert(`${m.name}仅适用于${m.minYear}～${m.maxYear}年。`);if(ip.year>=INNER_POWER_MAX_YEAR)return alert('内力已经达到280年上限。');const used=Number(ip.medicineUsed?.[key]||0),gain=medicinePower(key,used);state.innerPower.items[key]-=1;ip.medicineUsed[key]=used+1;ip.power=Number(ip.power||0)+gain;advanceInnerPower(ip);commit();alert(`${HEROES[selectedGrowthHero].name}服用${m.name}，内力 +${fmt(gain)}。`);}
function attemptInnerBreakthrough(usePill=false){ensureGrowthHero();const ip=state.heroes[selectedGrowthHero]?.innerPower;if(!ip)return;const year=readyBreakthroughYear(ip);if(!year)return alert('当前尚未到十年瓶颈。');const now=Date.now();if(Number(ip.recoveryUntil||0)>now)return alert(`仍在调息，还需${formatRemain(ip.recoveryUntil-now)}。`);const info=breakthroughInfo(year);let rate=info.rateBp;if(usePill){if(Number(state.innerPower?.items?.dingshen||0)<=0)return alert('定神丸不足。');state.innerPower.items.dingshen-=1;rate+=calmingPillRateBonus(year);}rate=Math.min(10000,rate);if(Math.floor(Math.random()*10000)<rate){ip.passed=Array.isArray(ip.passed)?ip.passed:[];if(!ip.passed.includes(year))ip.passed.push(year);ip.year=year;ip.recoveryUntil=0;advanceInnerPower(ip);commit();alert(`突破成功！${HEROES[selectedGrowthHero].name}内力达到${year}年。`);}else{ip.recoveryUntil=Date.now()+info.recoverySec*1000;commit();alert(`突破失败，进入调息 ${formatRemain(info.recoverySec*1000)}。`);}}
'''
s=s.replace(marker,inner_funcs+marker)
