bp=Path('src/battle.js');b=bp.read_text();b=b.replace("initialRage:rageEffect?.initialRage||0","initialRage:(rageEffect?.initialRage||0)+Number(s.initialRage||0)");b=b.replace("return {amount:Math.max(1,Math.round(base*multiplier*variance*(crit?1.5:1))),miss:false,crit};","const bonus=1+Number(attacker.damageBonus||0)/100,reduction=Math.max(.2,1-Number(target.damageReduction||0)/100); return {amount:Math.max(1,Math.round(base*multiplier*variance*(crit?1.5:1)*bonus*reduction)),miss:false,crit};");bp.write_text(b)
